"""Practice controls and two deliberately authored hints for each 1405 question.

These controls are a separate learning layer. They never replace or edit the
printed source prompt/reference answer, which are rendered from pinned PDFs.
Rows use the source part order. A slash in a choice is literal, not a fraction parser.
"""
def M(rows, h1, h2, title='پاسخ‌های سؤال'):
    # Each row is: printed part / correct response / two or more distractors.
    pairs=[]
    for row in rows.split('\n'):
        bits=row.split('|');assert len(bits)>=4,row
        pairs.append(dict(left=bits[0],right=bits[1],choices=bits[1:]))
    return dict(kind='match',prompt='پاسخ هر قسمت را انتخاب کن.',pairs=pairs,choices=[],allowTokenReuse=True,
                hint1=h1,hint2=h2,_title=title)

def U(correct,wrong,pick,h1,h2,title='انتخاب پاسخ'):
    return dict(kind='multi',prompt=f'{pick} مورد را انتخاب کن.',pick=pick,
        options=[dict(text=t,correct=True) for t in correct.split('|')]+[dict(text=t,correct=False) for t in wrong.split('|')],
        hint1=h1,hint2=h2,_title=title)

def O(items,h1,h2,title='ترتیب مراحل'):
    parts=items.split('|')
    return dict(kind='order',prompt='مراحل را به ترتیب قرار بده.',items=parts,correctOrder=list(range(len(parts))),hint1=h1,hint2=h2,_title=title)

